const jobs = $('Get Jobs').all().map(i => i.json).filter(j => j.id);
const companies = $('Get Companies').all().map(i => i.json).filter(c => c.id);
const contacts = $('Get Contacts').all().map(i => i.json).filter(c => c.id);
const outreach = $('Get Outreach').all().map(i => i.json).filter(o => o.id);

const norm = s => String(s).toLowerCase().replace(/[^a-z]/g, '').replace(/^property/, '');

// Reads one Notion property value, raw API format or simplified format
const val = p => {
  if (p == null) return '';
  if (typeof p !== 'object') return p;
  if (Array.isArray(p)) return p;
  switch (p.type) {
    case 'title': return (p.title || []).map(t => t.plain_text || '').join('');
    case 'rich_text': return (p.rich_text || []).map(t => t.plain_text || '').join('');
    case 'select': return p.select ? p.select.name : '';
    case 'status': return p.status ? p.status.name : '';
    case 'multi_select': return (p.multi_select || []).map(s => s.name);
    case 'date': return p.date ? p.date.start : '';
    case 'number': return p.number == null ? '' : p.number;
    case 'checkbox': return !!p.checkbox;
    case 'url': return p.url || '';
    case 'relation': return (p.relation || []).map(r => r.id);
    case 'formula': return p.formula ? (p.formula.string ?? p.formula.number ?? p.formula.boolean ?? '') : '';
    case 'rollup': return p.rollup ? (p.rollup.number ?? '') : '';
    default: return p.name || p.start || '';
  }
};

// Finds a property by name in either format
const get = (j, name) => {
  const want = norm(name);
  const props = (j.properties && typeof j.properties === 'object') ? j.properties : j;
  const k = Object.keys(props).find(k => norm(k) === want);
  return k ? val(props[k]) : '';
};

// The page title, whatever the title column is called
const titleOf = j => {
  if (j.name && typeof j.name === 'string') return j.name;
  const props = j.properties || {};
  const k = Object.keys(props).find(k => props[k] && props[k].type === 'title');
  return k ? val(props[k]) : '';
};

const coName = {}; companies.forEach(c => { coName[c.id] = titleOf(c); });
const ctName = {}; contacts.forEach(c => { ctName[c.id] = titleOf(c); });

const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const timeOf = j => {
  const s = get(j, 'date found');
  const t = s ? new Date(s).getTime() : 0;
  return isNaN(t) ? 0 : t;
};

const now = Date.now();
const WINDOW = 20 * 3600 * 1000; // "new" = found in the last 20 hours (this morning's run)

const company = j => {
  const c = get(j, 'company');
  return (Array.isArray(c) && c[0]) ? (coName[c[0]] || '') : '';
};
const verdict = j => String(get(j, 'claude verdict') || '');
const decision = j => String(get(j, 'decision') || '');
const undecided = j => !decision(j) || decision(j) === 'Undecided';
const preScore = j => { const v = get(j, 'pre score'); return v === '' ? '-' : v; };
const nContacts = j => { const c = get(j, 'contacts'); return Array.isArray(c) ? c.length : 0; };
const rank = v => v === 'Apply' ? 0 : v === 'Reach out first' ? 1 : v === '' ? 2 : 3;

const jobLine = j =>
  '<li><a href="' + esc(j.url) + '">' + esc(titleOf(j)) + '</a>, ' + esc(company(j)) +
  ' · score ' + esc(preScore(j)) +
  ' · <b>' + esc(verdict(j) || 'not analyzed yet') + '</b>' +
  (nContacts(j) ? ' · ' + nContacts(j) + ' contact(s)' : '') +
  '</li>';

const section = (title, arr, fn, max) => {
  const items = arr.slice(0, max || 15);
  const more = arr.length > items.length ? '<p>+ ' + (arr.length - items.length) + ' more in Notion</p>' : '';
  return '<h3>' + title + ' (' + arr.length + ')</h3>' +
    (items.length ? '<ul>' + items.map(fn).join('') + '</ul>' + more : '<p>Nothing right now.</p>');
};

// 1. New jobs: found in the last 20 hours, not decided yet, not auto-skipped
const newJobs = jobs.filter(j => now - timeOf(j) <= WINDOW && timeOf(j) > 0 && verdict(j) !== 'Skip' && undecided(j))
  .sort((a, b) => rank(verdict(a)) - rank(verdict(b)));

// 2. Jobs waiting for your decision (analyzed by Claude, not decided yet, not "Skip")
const toDecide = jobs.filter(j => verdict(j) && verdict(j) !== 'Skip' && undecided(j))
  .sort((a, b) => rank(verdict(a)) - rank(verdict(b)));

// 3. Outreach drafts waiting to be sent
const drafts = outreach.filter(o => String(get(o, 'status')) === 'Draft');
const draftLine = o => {
  const c = get(o, 'contact');
  const id = Array.isArray(c) ? c[0] : null;
  return '<li><a href="' + esc(o.url) + '">' + esc(titleOf(o)) + '</a>' + (id && ctName[id] ? ' · ' + esc(ctName[id]) : '') + '</li>';
};

// 4. Will Apply but no materials yet
const needMaterials = jobs.filter(j => decision(j) === 'Will Apply' && !get(j, 'materials ready'));

const html =
  '<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5">' +
  '<h2>Job search briefing</h2>' +
  section('New jobs today', newJobs, jobLine, 15) +
  section('Waiting for your decision', toDecide, jobLine, 10) +
  section('Outreach drafts to review and send', drafts, draftLine, 10) +
  section('Will Apply, materials not ready', needMaterials, jobLine, 10) +
  '<p style="color:#888;font-size:12px">debug: jobs=' + jobs.length +
  ', with date=' + jobs.filter(j => timeOf(j) > 0).length +
  ', new=' + newJobs.length +
  ', outreach=' + outreach.length + '</p>' +
  '</div>';

const today = new Date().toISOString().slice(0, 10);
const subject = 'Job briefing ' + today + ': ' + newJobs.length + ' new, ' + toDecide.length + ' to decide, ' + drafts.length + ' drafts';

return [{ json: { subject, html } }];
